// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }

    function testFuzz_property(uint256 amount) public {
        // admissible domain: a strictly positive, realistic wei balance on the contract
        amount = bound(amount, 1, 1e24);

        // give the contract itself a balance of `amount`
        vm.deal(address(c), amount);

        // only the deployer (this test contract, c's owner) may call sudicideAnyone;
        // no prank needed — msg.sender here IS __owner.
        uint256 callerBefore = address(this).balance;

        c.sudicideAnyone();

        // RULE: destroying the contract pays its entire balance to the caller (msg.sender).
        // Reference C: caller's balance grows by exactly `amount`.
        // Mutant M: sends the balance to address(this) before deletion, so it is lost
        // and the caller's balance is unchanged.
        assertTrue(address(this).balance == callerBefore + amount);
    }
}
